<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import { ElMessage, ElMessageBox } from 'element-plus';
import { api } from '../api';
import { applicationTypes, applicationStates, stateTone, admissionDate, admissionTime, downloadMaterial } from '../admission';
import { subjectError } from '../subject-management';
import { useResponsiveDrawer } from '../province-monitoring';
import { useSessionStore } from '../stores/session';
const props=defineProps<{modelValue:boolean;applicationId:string;options:any}>(),emit=defineEmits<{'update:modelValue':[value:boolean];changed:[];edit:[item:any]}>();
const open=computed({get:()=>props.modelValue,set:value=>emit('update:modelValue',value)}),session=useSessionStore(),router=useRouter(),width=useResponsiveDrawer(940),enterprise=computed(()=>session.user?.portal==='ENTERPRISE');
const detail=ref<any>(null),loading=ref(false),error=ref(''),busy=ref(false),tab=ref('info'),check=ref<any>(null),reviewOpen=ref(false),signOpen=ref(false),snapshot=ref<any>(null),category=ref('申报材料');let generation=0;
const handle=reactive({action:'APPROVE',comment:''}),sign=reactive({vehicleId:'',licenseNo:'',issuedAt:'',expiresAt:'',regionIds:[] as string[],allowedHours:'06:00-22:00',speedLimit:20,remark:''});
const editable=computed(()=>enterprise.value&&session.user?.permissions.includes('admission:application:write')&&['DRAFT','RETURNED'].includes(detail.value?.status));
const signRegions=computed(()=>props.options.regions?.filter((r:any)=>!r.enterpriseId||r.enterpriseId===detail.value?.enterpriseId)??[]);
const actions:Record<string,string>={SUBMIT:'提交申请',RESUBMIT:'补正后重新提交',APPROVE_NODE:'节点审核通过',APPROVE:'审核通过',RETURN:'退回补正',REJECT:'驳回申请',ISSUE_LICENSE:'结果签发',WITHDRAW:'撤回申请',REOPEN:'签发前退回补正'};
async function load(){if(!open.value||!props.applicationId)return;const request=++generation;loading.value=true;error.value='';detail.value=null;check.value=null;try{const result=await api<any>(`/admission/applications/${props.applicationId}`);if(request===generation)detail.value=result}catch(e){if(request===generation)error.value=subjectError(e)}finally{if(request===generation)loading.value=false}}
watch(()=>[props.modelValue,props.applicationId],()=>{if(open.value){tab.value='info';load()}else generation++},{immediate:true});onBeforeUnmount(()=>generation++);
async function precheck(){busy.value=true;try{check.value=await api(`/admission/applications/${detail.value.id}/precheck`);if(check.value.valid)ElMessage.success('当前提交条件检查通过')}catch(e){ElMessage.error(subjectError(e))}finally{busy.value=false}}
async function submit(){await precheck();if(!check.value?.valid)return;try{await ElMessageBox.confirm('提交后进入审核，审核期间不能修改申报内容。','提交申请',{confirmButtonText:'提交',cancelButtonText:'取消'});busy.value=true;await api(`/admission/applications/${detail.value.id}/submit`,{method:'POST'});ElMessage.success('申请已提交');emit('changed');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(subjectError(e))}finally{busy.value=false}}
async function withdraw(){try{await ElMessageBox.confirm('撤回后结束本次申请，后续可重新发起业务申请。','撤回申请',{confirmButtonText:'确认撤回',cancelButtonText:'取消',type:'warning'});busy.value=true;await api(`/admission/applications/${detail.value.id}/withdraw`,{method:'POST'});ElMessage.success('申请已撤回');emit('changed');await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(subjectError(e))}finally{busy.value=false}}
function startReview(){Object.assign(handle,{action:'APPROVE',comment:''});reviewOpen.value=true}
async function reopen(){let comment='';try{const answer=await ElMessageBox.prompt('退回后需企业补充材料并重新提交审核，请填写原因。','退回补正',{inputType:'textarea',inputValidator:value=>!!value?.trim()||'请填写退回原因',confirmButtonText:'确认退回',cancelButtonText:'取消'});comment=answer.value??''}catch{return}busy.value=true;try{await api(`/admission/applications/${detail.value.id}/reopen`,{method:'POST',body:JSON.stringify({action:'RETURN',comment})});ElMessage.success('已退回企业补正');emit('changed');await load()}catch(e){ElMessage.error(subjectError(e))}finally{busy.value=false}}
async function review(){if(handle.action!=='APPROVE'&&!handle.comment.trim())return ElMessage.warning('退回或驳回请填写办理意见');busy.value=true;try{await api(`/admission/tasks/${detail.value.currentTask.id}/handle`,{method:'POST',body:JSON.stringify(handle)});reviewOpen.value=false;ElMessage.success('办理结果已保存');emit('changed');await load()}catch(e){ElMessage.error(subjectError(e))}finally{busy.value=false}}
async function startSign(){await precheck();if(!check.value?.valid)return;const d=detail.value,conditions=d.details??{};Object.assign(sign,{vehicleId:'',licenseNo:'',issuedAt:admissionDate(new Date().toISOString()),expiresAt:admissionDate(d.requestedExpiresAt||d.roadTestEndAt||d.targetLicense?.expiresAt).replace('—',''),regionIds:conditions.regionIds??[],allowedHours:conditions.allowedHours??'06:00-22:00',speedLimit:conditions.speedLimit??20,remark:''});signOpen.value=true}
async function issue(){busy.value=true;try{const payload:any=detail.value.applicationType==='LICENSE_EXIT'?{}:{issuedAt:sign.issuedAt,expiresAt:sign.expiresAt,regionIds:sign.regionIds,allowedHours:sign.allowedHours,speedLimit:sign.speedLimit,remark:sign.remark};if(sign.vehicleId)payload.vehicleId=sign.vehicleId;if(sign.licenseNo)payload.licenseNo=sign.licenseNo;await api(`/admission/applications/${detail.value.id}/issue-license`,{method:'POST',body:JSON.stringify(payload)});signOpen.value=false;ElMessage.success('结果已签发并更新许可台账');emit('changed');await load()}catch(e){ElMessage.error(subjectError(e))}finally{busy.value=false}}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;if(file.size>2*1024*1024){input.value='';return ElMessage.warning('每份材料不超过2MB')}busy.value=true;try{const data=new FormData();data.append('file',file);data.append('category',category.value);await api(`/admission/applications/${detail.value.id}/materials`,{method:'POST',body:data});ElMessage.success('材料已上传');await load();tab.value='materials'}catch(e){ElMessage.error(subjectError(e))}finally{busy.value=false;input.value=''}}
async function removeMaterial(material:any){try{await ElMessageBox.confirm(`确定移除“${material.name}”？已提交的历史版本仍会保留。`,'移除材料',{confirmButtonText:'移除',cancelButtonText:'取消'});busy.value=true;await api(`/admission/applications/${detail.value.id}/materials/${material.id}`,{method:'DELETE'});await load();tab.value='materials'}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(subjectError(e))}finally{busy.value=false}}
async function download(material:any){try{await downloadMaterial(detail.value.id,material)}catch(e){ElMessage.error(subjectError(e))}}
function showSnapshot(item:any){try{snapshot.value=JSON.parse(item.snapshotJson)}catch{ElMessage.warning('历史版本不可用')}}
function viewPermit(){const id=detail.value.issuedLicenses?.[0]?.id??detail.value.targetLicenseId;open.value=false;router.push({path:enterprise.value?'/enterprise/licenses':'/admission/licenses',query:id?{licenseId:id}:{}})}
</script>
<template>
<el-drawer v-model="open" title="业务办理详情" :size="width" class="subject-drawer" destroy-on-close :close-on-click-modal="!busy" :show-close="!busy">
  <div v-if="error" class="subject-error" role="alert"><strong>业务详情加载失败</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div><el-skeleton v-else-if="loading" :rows="9" animated/>
  <template v-else-if="detail"><div class="subject-detail-title"><div><h2>{{detail.title}}</h2><p>{{detail.businessNo}} · {{applicationTypes[detail.applicationType]}}</p></div><el-tag :type="stateTone(detail.status)">{{applicationStates[detail.status]}}</el-tag></div>
    <div v-if="check&&!check.valid" class="admission-check" role="alert"><strong>以下办理条件需要补充或处理</strong><ul><li v-for="item in check.issues" :key="item">{{item}}</li></ul></div>
    <el-tabs v-model="tab"><el-tab-pane label="申报信息" name="info"/><el-tab-pane :label="`申报材料（${detail.materials.length}）`" name="materials"/><el-tab-pane label="办理记录" name="history"/></el-tabs>
    <template v-if="tab==='info'"><dl class="subject-detail-grid"><div><dt>申请企业</dt><dd>{{detail.enterprise?.name||detail.enterpriseNameSnapshot}}</dd></div><div><dt>申请人</dt><dd>{{detail.applicantUser?.displayName}}</dd></div><div><dt>当前环节</dt><dd>{{detail.currentNodeName||(detail.status==='APPROVED'?'结果签发':applicationStates[detail.status])}}</dd></div><div><dt>提交时间</dt><dd>{{admissionTime(detail.submittedAt)}}</dd></div><div><dt>原通行许可</dt><dd>{{detail.targetLicense?.licenseNo||'—'}}</dd></div><div><dt>申请有效期至</dt><dd>{{admissionDate(detail.requestedExpiresAt||detail.roadTestEndAt)}}</dd></div><div v-if="detail.roadTestStartAt"><dt>起止日期</dt><dd>{{admissionDate(detail.roadTestStartAt)}} 至 {{admissionDate(detail.roadTestEndAt)}}</dd></div><div v-if="detail.details.allowedHours"><dt>运行条件</dt><dd>{{detail.details.allowedHours}} · 限速 {{detail.details.speedLimit}} km/h</dd></div><div v-if="detail.details.regionIds?.length" class="wide"><dt>拟通行区域</dt><dd>{{detail.details.regionIds.map((id:string)=>options.regions?.find((r:any)=>r.id===id)?.name||'历史区域').join('、')}}</dd></div><div v-for="field in [{key:'testPlan',label:'实施方案'},{key:'safetyMeasures',label:'安全保障措施'},{key:'roadTestRoute',label:'路线说明'},{key:'operationPlan',label:'运营方案'},{key:'qualificationSummary',label:'资质说明'},{key:'renewalReason',label:'续期原因'}].filter(f=>detail[f.key])" :key="field.key" class="wide"><dt>{{field.label}}</dt><dd>{{detail[field.key]}}</dd></div><div v-if="detail.details.changeReason" class="wide"><dt>变更 / 退出原因</dt><dd>{{detail.details.changeReason}}</dd></div></dl>
      <h3 class="subject-detail-section">关联车辆</h3><el-table :data="detail.vehicles" empty-text="本事项未关联车辆"><el-table-column label="车辆" min-width="180"><template #default="{row}">{{row.vehicle.name}}</template></el-table-column><el-table-column label="车辆编号" min-width="180"><template #default="{row}">{{row.vehicle.unifiedCode||row.vehicle.businessNo}}</template></el-table-column></el-table>
      <h3 v-if="detail.issuedLicenses?.length" class="subject-detail-section">签发结果</h3><el-button v-for="item in detail.issuedLicenses" :key="item.id" link type="primary" @click="viewPermit">{{item.licenseNo}}</el-button>
    </template>
    <template v-else-if="tab==='materials'"><p class="subject-detail-caption">支持PDF、PNG、JPG，每份不超过2MB；补正时会保留上次提交的材料版本。</p><div v-if="editable" class="admission-upload"><el-select v-model="category" aria-label="材料分类"><el-option v-for="name in ['申报材料','测试报告','安全方案','资格证明','变更说明','其他材料']" :key="name" :label="name" :value="name"/></el-select><input type="file" aria-label="上传申报材料" accept=".pdf,.png,.jpg,.jpeg" :disabled="busy" @change="upload"/></div><div class="admission-materials"><div v-for="material in detail.materials" :key="material.id" class="admission-material"><div><strong>{{material.name}}</strong><small>{{material.category}} · {{Math.ceil(material.size/1024)}}KB · {{admissionTime(material.uploadedAt)}}</small></div><div><el-button link type="primary" @click="download(material)">下载</el-button><el-button v-if="editable" link type="danger" :disabled="busy" @click="removeMaterial(material)">移除</el-button></div></div><el-empty v-if="!detail.materials.length" description="尚未上传申报材料" :image-size="64"/></div></template>
    <el-timeline v-else class="admission-timeline"><el-timeline-item v-for="item in detail.approvalHistories" :key="item.id" :timestamp="admissionTime(item.createdAt)" placement="top"><strong>{{actions[item.action]||item.action}} · {{item.actorName}}</strong><p>{{item.nodeName||'业务办理'}} · {{item.comment||'无补充意见'}}</p><el-button v-if="item.snapshotJson" link type="primary" @click="showSnapshot(item)">查看申报版本</el-button></el-timeline-item></el-timeline>
  </template>
  <template #footer><el-button :disabled="busy" @click="open=false">关闭</el-button><template v-if="detail"><el-button v-if="editable" :disabled="busy" @click="emit('edit',detail)">编辑信息</el-button><el-button v-if="enterprise&&session.user?.permissions.includes('admission:application:write')&&['DRAFT','RETURNED','IN_REVIEW'].includes(detail.status)" :disabled="busy" @click="withdraw">撤回</el-button><el-button v-if="editable" :loading="busy" @click="precheck">检查条件</el-button><el-button v-if="editable" type="primary" :loading="busy" @click="submit">提交申请</el-button><el-button v-if="detail.canHandle" type="primary" :disabled="busy" @click="startReview">办理</el-button><el-button v-if="detail.canIssue&&session.user?.permissions.includes('admission:approval:handle')&&!detail.issuedLicenses?.length&&!detail.result?.licenseId" :disabled="busy" @click="reopen">退回补正</el-button><el-button v-if="detail.canIssue" type="primary" :disabled="busy" @click="startSign">签发结果</el-button><el-button v-if="detail.status==='COMPLETED'&&(detail.issuedLicenses?.length||detail.targetLicenseId)" type="primary" @click="viewPermit">查看通行许可</el-button></template></template>
</el-drawer>
<el-dialog v-model="reviewOpen" title="办理审核" width="540px" class="subject-editor" :close-on-click-modal="!busy" :show-close="!busy"><el-form label-position="top"><el-form-item label="办理结论"><el-radio-group v-model="handle.action" :disabled="busy"><el-radio value="APPROVE">通过</el-radio><el-radio value="RETURN">退回补正</el-radio><el-radio value="REJECT">驳回</el-radio></el-radio-group></el-form-item><el-form-item label="办理意见"><el-input v-model="handle.comment" type="textarea" :rows="4" maxlength="1000" :disabled="busy"/></el-form-item></el-form><template #footer><el-button :disabled="busy" @click="reviewOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="review">确认办理</el-button></template></el-dialog>
<el-dialog v-model="signOpen" title="结果签发" width="700px" class="subject-editor" :close-on-click-modal="!busy" :show-close="!busy"><p v-if="detail?.applicationType==='LICENSE_EXIT'" class="subject-detail-caption">确认签发后将注销原许可，并保留历史记录。</p><el-form v-else label-position="top" class="subject-form" :disabled="busy"><el-form-item v-if="['ROAD_TEST','DEMONSTRATION'].includes(detail?.applicationType)" label="签发车辆" class="wide"><el-select v-model="sign.vehicleId" aria-label="签发车辆" clearable placeholder="全部未签发车辆"><el-option v-for="link in detail?.vehicles?.filter((v:any)=>!detail.issuedLicenses?.some((l:any)=>l.vehicleId===v.vehicleId))" :key="link.vehicleId" :value="link.vehicleId" :label="link.vehicle.name"/></el-select></el-form-item><el-form-item label="签发日期"><el-date-picker v-model="sign.issuedAt" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="有效期至"><el-date-picker v-model="sign.expiresAt" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="通行区域" class="wide"><el-select v-model="sign.regionIds" aria-label="签发通行区域" multiple filterable><el-option v-for="item in signRegions" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item><el-form-item label="允许时段"><el-input v-model="sign.allowedHours"/></el-form-item><el-form-item label="限速（km/h）"><el-input-number v-model="sign.speedLimit" :min="1" :max="80"/></el-form-item><el-form-item label="备注" class="wide"><el-input v-model="sign.remark" type="textarea" :rows="2" maxlength="500"/></el-form-item><p class="admission-form-note">许可编号自动生成；批量签发会逐车生成许可并记录本次批准的区域边界和运行条件。</p></el-form><template #footer><el-button :disabled="busy" @click="signOpen=false">取消</el-button><el-button type="primary" :loading="busy" @click="issue">确认签发</el-button></template></el-dialog>
<el-dialog :model-value="!!snapshot" title="历史申报版本" width="720px" class="subject-editor" @close="snapshot=null"><template v-if="snapshot"><dl class="subject-detail-grid"><div><dt>申请名称</dt><dd>{{snapshot.title}}</dd></div><div><dt>申请编号</dt><dd>{{snapshot.businessNo}}</dd></div><div><dt>业务类型</dt><dd>{{applicationTypes[snapshot.applicationType]}}</dd></div><div><dt>企业</dt><dd>{{snapshot.enterprise?.name}}</dd></div><div class="wide"><dt>实施方案</dt><dd>{{snapshot.testPlan||snapshot.operationPlan||snapshot.details?.changeReason||snapshot.renewalReason||'—'}}</dd></div></dl><div v-for="material in snapshot.materials" :key="material.id" class="admission-material"><strong>{{material.name}}</strong><el-button link type="primary" @click="download(material)">下载原材料</el-button></div></template><template #footer><el-button @click="snapshot=null">关闭</el-button></template></el-dialog>
</template>
